 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    rectangles = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen
                                and grid[ny][nx] == color):
                            seen.add((ny, nx))
                            q.append((ny, nx))
            top = min(y for y, _ in cells)
            bottom = max(y for y, _ in cells)
            left = min(x for _, x in cells)
            right = max(x for _, x in cells)
            box_area = (bottom - top + 1) * (right - left + 1)
            if box_area >= 10 and len(cells) / box_area >= 0.55:
                rectangles.append((top, bottom, left, right, color))
    out = [[background for _ in range(w)] for _ in range(h)]
    for top, bottom, left, right, color in rectangles:
        for y in range(top, bottom + 1):
            for x in range(left, right + 1):
                out[y][x] = color
    return out
